item.command:
/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic a,
    input  logic b,
    input  logic c,
    input  logic d,
    output logic q
);
    assign q = ~"'^{a, b, c, d};
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'"'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic a, b, c, d;
    wire q;
    localparam logic [15:0] EXPECTED = 16'"'b1001011001101001;
    TopModule dut (.a(a), .b(b), .c(c), .d(d), .q(q));
    initial begin
        for (integer i = 0; i < 16; i = i + 1) begin
            {a, b, c, d} = i[3:0];
            #1;
            if (q "'!== EXPECTED[i])
                $fatal(1, "FAIL input=%04b expected=%b actual=%b", {a,b,c,d}, EXPECTED[i], q);
        end
        $display("PASS: all 16 waveform input combinations");
        $finish;
    end
    initial begin
        #100;
        $fatal(1, "FAIL: testbench timeout");
    end
endmodule
EOF
 timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > dev_compile.log 2>&1
compile_status=$?
cat dev_compile.log
printf '"'compile_exit_code=%s\\n' \""'$compile_status"
if [ "$compile_status" -eq 0 ]; then
    timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > dev_sim.log 2>&1
    sim_status=$?
    cat dev_sim.log
    printf '"'simulation_exit_code=%s\\n' \""'$sim_status"
fi'

